  if (next.kind === "polyphony") pose = polyphonyPose(next.t, fromX, trick.facing);
  else if (next.kind === "partial") pose = partialPose(next.t, fromX, trick.facing);
  else if (next.kind === "timbre") pose = timbrePose(next.t, fromX, trick.facing);
  else if (next.kind === "resonance") pose = resonancePose(next.t, fromX, trick.facing);
  else if (next.kind === "formant") pose = formantPose(next.t, fromX, trick.facing);
  else pose = dyadPose(next.t, fromX, trick.facing);
  next.x = pose.x;
  next.lift = pose.lift;
  next.rot = pose.rot;
  next.anim = pose.anim;
  if (u >= 1) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
